# 插入句子位置題的選項是 [1]～[4]（optionOrder 會照順序排），正解仍寫在第一個
def S(title, time, passages, qs):
    return {"title": title, "time": time, "passages": passages,
            "qs": [{"q": q, "opts": o, "ans": 0, "exp": e} for q, o, e in qs]}

